document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("main-textarea"),e=document.getElementById("save-status");window.location.hostname;let o=null;t.addEventListener("input",()=>{e.textContent="Editing...",e.style.color="#888",clearTimeout(o),o=setTimeout(()=>{!async function(){const o=t.value;e.textContent="Saving...",e.style.color="#888";try{const t={message:o};(await fetch("http://192.168.3.85:9090/todo/",{method:"POST",headers:{accept:"*/*","Content-Type":"application/json"},body:JSON.stringify(t)})).ok?(e.textContent="Auto-saved ✓",e.style.color="#2ecc71",setTimeout(()=>{"Auto-saved ✓"===e.textContent&&(e.textContent="")},3e3)):(e.textContent="Save failed ✕",e.style.color="#e74c3c")}catch(t){console.error("Error sending message:",t),e.textContent="Network error, save failed ✕",e.style.color="#e74c3c"}}()},1e3)}),async function(){try{e.textContent="Loading...";const o=await fetch("http://192.168.3.85:9090/todo/getMessage",{method:"GET",headers:{accept:"*/*"}});if(!o.ok)throw new Error("Network response was not ok");const n=await o.json();if(n&&n.length>0){const e=n[n.length-1].message||"";t.value=e}e.textContent="Latest content loaded",e.style.color="#888",setTimeout(()=>{"Latest content loaded"===e.textContent&&(e.textContent="")},2e3)}catch(t){console.error("Failed to fetch handover items:",t),e.textContent="Failed to load",e.style.color="#e74c3c"}}()});